  // Setting up an agent on one's own computer (agent-status.ts, tokens-settings.ts, the 3D room's first-run guide)
  'Copy it now - you will not see it again. Run this line on the computer the agent will work on, and keep it running:': 'Şimdi kopyalayın - bir daha göremeyeceksiniz. Bu satırı ajanın çalışacağı bilgisayarda çalıştırın ve açık tutun:',
  'for an agent you run yourself, in a full checkout': 'kaynak kodun tamamıyla kendiniz çalıştırdığınız bir ajan için',
  'Copy the line': 'Satırı kopyala',
  'Copy the line, with the token': 'Satırı anahtarla birlikte kopyala',
  'The browser would not copy - select the line instead.': 'Tarayıcı kopyalamadı - satırı seçip kopyalayın.',
  'Set up your agent': 'Ajanınızı kurun',
  'the seed, and its README': 'seed deposu ve README',
  'Make a token': 'Anahtar oluşturun',
  'Below, under New token: name it after the computer it will run on (e.g. laptop). It is shown once - the line with it comes up right there.': 'Aşağıda, Yeni anahtar bölümünde: çalışacağı bilgisayarın adını verin (ör. laptop). Anahtar bir kez gösterilir - onu içeren satır hemen orada çıkar.',
  'Run the line on your computer': 'Satırı bilgisayarınızda çalıştırın',
  "Needs git, Python 3.12 or newer and Claude Code, signed in. On Windows the line runs the agent in WSL. The token is kept in .env in that folder, readable only by you - never commit it or paste it anywhere else.": "git, Python 3.12 ya da üstü ve oturum açılmış Claude Code gerekir. Windows'ta satır ajanı WSL içinde çalıştırır. Anahtar o klasördeki .env dosyasında, yalnızca sizin okuyabileceğiniz şekilde saklanır - asla commit etmeyin, başka bir yere yapıştırmayın.",
  'Keep it running': 'Açık tutun',
  'The agent is what does the work on the notes you queue: keep it running on your computer the whole time you develop. If it stops, notes wait in the queue until it is back.': 'Kuyruğa aldığınız notlar üzerindeki işi ajan yapar: geliştirdiğiniz sürece bilgisayarınızda çalışır durumda tutun. Durursa notlar o geri gelene kadar kuyrukta bekler.',
  'start again, updated': 'güncelleyerek yeniden başlat',
  'stop it': 'durdur',
  'watch it': 'izle',
  'Connect your agent': 'Ajanınızı bağlayın',
  'The work on your notes is done by an AI agent (Claude Code) on your own computer. Make a token in Agent tokens, run the line on your computer, and keep it running the whole time you develop: if it stops, notes wait in the queue.': 'Notlarınız üzerindeki işi kendi bilgisayarınızdaki bir yapay zekâ ajanı (Claude Code) yapar. Ajan anahtarları bölümünde bir anahtar oluşturun, satırı bilgisayarınızda çalıştırın ve geliştirdiğiniz sürece açık tutun: durursa notlar kuyrukta bekler.',
  'checking…': 'denetleniyor…',
