  'PowerShell; runs the agent in WSL': 'PowerShell; ajanı WSL içinde çalıştırır',
  'Put your token in place of your-token - or copy the whole line in Agent tokens, right after making the token.': 'your-token yerine anahtarınızı yazın - ya da anahtarı oluşturduktan hemen sonra satırın tamamını Ajan anahtarları bölümünden kopyalayın.',
  'handing out agent tokens takes an editor, an admin or an owner': 'ajan anahtarı vermek için düzenleyici, yönetici ya da sahip olmak gerekir',
