  'Created': 'Oluşturuldu',
  'Delete this token for good? It is still active: it is revoked first, and the agent using it is stopped at once. Its usage counts go with it; the audit trail keeps what it did.': 'Bu anahtar kalıcı olarak silinsin mi? Hâlâ etkin: önce geri alınır ve onu kullanan ajan hemen durdurulur. Kullanım sayıları da silinir; denetim kaydı yaptıklarını saklar.',
  'Delete this token for good? Its usage counts go with it; the audit trail keeps what it did.': 'Bu anahtar kalıcı olarak silinsin mi? Kullanım sayıları da silinir; denetim kaydı yaptıklarını saklar.',
