  'Programs such as AI agents sign in to Workbench with an agent token (rlat_…) instead of a password. A token is at most an editor, can be kept to one room and taken back at any time; everything the agent does is recorded under the name you give it.': 'Yapay zekâ ajanları gibi programlar Workbench\'e şifre yerine bir ajan anahtarıyla (rlat_…) girer. Bir anahtar en fazla düzenleyici olabilir, tek bir odayla sınırlanabilir ve her an geri alınabilir; ajanın yaptığı her şey verdiğiniz adla kaydedilir.',
  'Read-only for you: handing out agent tokens takes an editor, an admin or an owner.': 'Sizin için salt okunur: ajan anahtarı vermek için düzenleyici, yönetici veya sahip olmak gerekir.',
