  'warn at': 'uyarı',
  'The bar and the top bar turn the warning colour from this share of the budget': 'Çubuk ve üst bar bütçenin bu oranından itibaren uyarı rengine döner',
  'No budgets yet. Set a monthly budget for the total spend - and, if you like, separate ones for the LLM work at list prices, the electricity and the proxy - to see the month so far against them, where the month is heading, and a warning in the top bar near the limit.': 'Henüz bütçe yok. Toplam harcama için aylık bir bütçe - isterseniz liste fiyatlarıyla LLM işi, elektrik ve proxy için ayrı bütçeler - belirleyin; ayın şu ana kadarki durumunu, ay sonu tahminini ve sınıra yaklaşınca üst barda bir uyarı görün.',
  'The total is the subscriptions and other costs prorated to today, the electricity and the proxy traffic - and the LLM work at list prices when no subscription covers it. The month-end forecast keeps the fixed costs at their full month and runs the metered ones on at the month\'s daily average, or at the last 7 days\' rate while the month is under 7 days old or when spending has picked up. Crossing the warning and 100% each write one line in the activity log, once a month.': 'Toplam; bugüne oranlanmış abonelikler ve diğer giderler, elektrik ve proxy trafiğidir - hiçbir abonelik karşılamıyorsa liste fiyatlarıyla LLM işi de eklenir. Ay sonu tahmini sabit giderleri tam ay olarak alır, ölçülenleri ayın günlük ortalamasıyla ya da ay 7 günden yeniyse veya harcama arttıysa son 7 günün hızıyla sürdürür. Uyarı eşiğini ve %100\'ü geçmek etkinlik günlüğüne ayda bir kez birer satır yazar.',
  'A budget has to be more than 0 - leave it empty for none.': 'Bütçe 0\'dan büyük olmalı - istemiyorsanız boş bırakın.',
  'The warning threshold is between 5% and 100%.': 'Uyarı eşiği %5 ile %100 arasında olmalı.',
