  // Settings > Telegram (telegram-settings.ts, telegram-profile.ts)
  'A Telegram bot for the whole server: the agents\' questions reach people on their phones, and answers, notes and messages come back the same way. The token stays on the server - once saved, only its last four characters are shown.': 'Sunucunun tamamı için bir Telegram botu: ajanların soruları insanların telefonlarına ulaşır; yanıtlar, notlar ve mesajlar da aynı yoldan geri gelir. Token sunucuda kalır - kaydedildikten sonra yalnızca son dört karakteri gösterilir.',
  'Preview - the server has no Telegram routes yet, so this shows a bot that is not set up.': 'Önizleme - sunucuda henüz Telegram yolları yok, bu yüzden kurulmamış bir bot gösteriliyor.',
  'Only the workspace\'s owners and admins can set up the bot. Linking your own Telegram is for everyone.': 'Botu yalnızca çalışma alanının sahipleri ve yöneticileri kurabilir. Kendi Telegram\'ını bağlamak herkese açık.',
