  'Open @BotFather in Telegram - Telegram\'s own bot for making bots - and make a new one. That is all BotFather is needed for: the name, descriptions, picture and commands are set here, in step 3.': 'Telegram\'da @BotFather\'ı açın - Telegram\'ın bot yapan kendi botu - ve yeni bir bot oluşturun. BotFather yalnızca bunun için gerekli: ad, açıklamalar, resim ve komutlar burada, 3. adımda ayarlanır.',
  'Send it to @BotFather. It asks for a display name (Workbench), then a username that ends in "bot" (redline_studio_bot), and answers with the token.': '@BotFather\'a gönderin. Önce bir görünen ad (Workbench), sonra "bot" ile biten bir kullanıcı adı (redline_studio_bot) ister ve token\'la yanıt verir.',
  'copied': 'kopyalandı',
  'copy': 'kopyala',
  'Open @BotFather': '@BotFather\'ı aç',
  'Its last message holds the token: 123456789:AA… Keep it secret; paste it in step 2.': 'Son mesajında token var: 123456789:AA… Gizli tutun; 2. adımda yapıştırın.',
