  'Checked with Telegram (getMe) before it is kept. A token of another bot unlinks everyone: their chats were with the old bot.': 'Saklanmadan önce Telegram\'la (getMe) denetlenir. Başka bir botun token\'ı herkesin bağlantısını kaldırır: sohbetleri eski botlaydı.',
  'Once the token is saved, set the bot\'s name, description, short description and picture here.': 'Token kaydedilince botun adını, açıklamasını, kısa açıklamasını ve resmini burada ayarlayın.',
