  'Long polling': 'Uzun yoklama',
  'fallback': 'yedek',
  'Telegram calls Workbench the moment something arrives. Needs the public https address; each call carries a secret header, and anything without it is refused.': 'Bir şey gelir gelmez Telegram Workbench\'i çağırır. Herkese açık https adresi gerekir; her çağrı gizli bir başlık taşır, taşımayan reddedilir.',
  'Workbench keeps asking Telegram for news. Works behind any firewall, with no public address - one server at a time.': 'Workbench Telegram\'a sürekli yeni bir şey var mı diye sorar. Her güvenlik duvarının arkasında, herkese açık adres olmadan çalışır - aynı anda tek sunucu.',
