  'in no route order': 'hiçbir yol sırasında değil',
  'EasyEDA turns a burst of part lookups away for a while, and some sites turn a crawler away. The route order says which way each lookup tries first - directly, through the proxy or through Jina - and which next. The model providers and everything else always go out directly.': 'EasyEDA art arda gelen parça sorgularını bir süre geri çevirir, bazı siteler de tarayıcıyı geri çevirir. Yol sırası her sorgunun önce hangi yolu deneyeceğini - doğrudan, proxy üzerinden ya da Jina üzerinden - ve sonra hangisini deneyeceğini belirler. Model sağlayıcıları ve geri kalan her şey her zaman doğrudan çıkar.',
