  'Proxy not set up': 'Proxy kurulu değil',
  'Where it is used: the Jina route in the Parts page\'s route order (above, or a maker\'s own) reads a web page through it - first, or after a site refuses or a page comes back empty without its script. robots.txt is still read here and obeyed, and only public addresses are sent. The Chat\'s web_search and web_read use Search and Reader.': 'Nerede kullanılır: Parçalar sayfasının yol sırasındaki (yukarıdaki ya da bir üreticinin kendi sırasındaki) Jina yolu bir web sayfasını onunla okur - ilk olarak ya da bir site reddettikten veya sayfa betiği olmadan boş geldikten sonra. robots.txt yine burada okunur ve uyulur, yalnızca herkese açık adresler gönderilir. Sohbet\'in web_search ve web_read araçları Search ve Reader\'ı kullanır.',
